import { useState } from 'react';
// Vérifie ces chemins : ils doivent correspondre exactement à tes dossiers
import Login from './Login';
import DashboardCandidat from './components/DashboardCandidat';
import DashboardRecruteur from './components/DashboardRecruteur';

function App() {
  const [user, setUser] = useState(null);

  // Debug : Si tu vois "undefined" dans la console, c'est que l'import a échoué
  console.log("Composant Login:", Login);
  console.log("Composant Candidat:", DashboardCandidat);
  console.log("Composant Recruteur:", DashboardRecruteur);

  return (
    <div className="main-app">
      {user ? (
        <div style={{ border: '5px solid red', padding: '20px' }}>
          {user.role === 'CANDIDAT' ? <DashboardCandidat /> : <DashboardRecruteur />}
        </div>
      ) : (
        <Login onLoginSuccess={setUser} />
      )}
    </div>
  );
}

export default App;
